Dear All,

I’m getting a ‘caught segfault -memory not mapped' error when using a custom distribution model and the stick_breaking() function in nimble. The models in the example below are a simplified version of what I am trying to achieve (I do realise there are better ways - e.g. using a Poisson model, but this cannot be done for a number of reasons). Both dTripleExponentialGrowth and dQuadrupleExponentialGrowth basically describe the probability of observing an event at a discrete time t given an exponential growth process where the growth rate has change points (2 and 3). My idea was to use the stick breaking algorithm as the prior of these changepoints. The example below runs perfectly fine with the two changepoint model (dTripleExponentialGrowth) and I am able to correctly estimate the true parameters of my model. However, when trying to fit the three changepoint model (dQuadrupleExponentialGrowth) I get the following error:

*** caught segfault ***

  address 0xfffffffffffffff8, cause 'memory not mapped'

Traceback:

  1: .Call("CALL_MCMC_run", niter, reset, resetMV, time, progressBar,     nburnin, thin, thin2, .basePtr)

2: mcmc$run(niter, nburnin = nburnin, thin = thinToUseVec[1], thin2 = thinToUseVec[2],     progressBar = progressBar)

3: runMCMC(Cmcmc, niter = niter, nburnin = nburnin, nchains = nchains,     inits = inits, setSeed = setSeed, progressBar = progressBar,     samples = samples, samplesAsCodaMCMC = samplesAsCodaMCMC,     summary = summary, WAIC = WAIC)

4: nimbleMCMC(code = model4, constants = constants4, data = data4,     niter = 20000, nchains = 1, thin = 1, nburnin = 5000, progressBar = TRUE,     monitors = c("r1", "r2", "r3", "r4", "chp1", "chp2", "chp3"),     inits = init4, samplesAsCodaMCMC = TRUE)

This doesn’t happen consistently all the time and occurs randomly at some point while the progress bar is progressing.  I assume this is a problem with my custom model, but the two versions are identical (indeed the plan was to write a generalised N-changepoint model) so I am not sure why one works and the other doesn't. Any help is greatly appreciated!

All Best,

Enrico

----

library(nimble)

## Custom Distributions ####

dTripleExponentialGrowth=nimbleFunction(

  run = function(x = integer(0),a=double(0),b=double(0),r1=double(0),r2=double(0),r3=double(0),mu1=double(0),mu2=double(0), log = integer(0)) {

    returnType(double(0))

    mu1 = round(mu1)

    mu2 = round(mu2)

    t1 = 1:(abs(mu1-a))

    t2 = 1:(abs(mu2-mu1))

    t3 = 1:(abs(b-mu2)+1)

    t1final = abs(mu1-a)

    t2final = abs(mu2-mu1)

    t3final = abs(b-mu2)+1

    n1 = numeric(t1final)

    n2 = numeric(t2final)

    n3 = numeric(t3final)

    for (i in 1:t1final) {n1[i] = (1+r1)^t1[i]}

    for (i in 1:t2final) {n2[i] = (n1[t1final])  * (1+r2)^t2[i]}

    for (i in 1:t3final) {n3[i] = (n2[t2final])  * (1+r3)^t3[i]}

    pop = c(n1,n2,n3)

    p = pop/sum(pop)

    logProb = dcat(a-x+1,prob=p,log=TRUE)

    if(log) {

      return(logProb)

    } else {

      return(exp(logProb))

    }

  })

rTripleExponentialGrowth = nimbleFunction(

  run = function(n=integer(0),a=double(0),b=double(0),r1=double(0),r2=double(0),r3=double(0),mu1=double(0),mu2=double(0)) {

    returnType(double(0))

    mu1 = round(mu1)

    mu2 = round(mu2)

    t1 = 1:(abs(mu1-a))

    t2 = 1:(abs(mu2-mu1))

    t3 = 1:(abs(b-mu2)+1)

    t1final = abs(mu1-a)

    t2final = abs(mu2-mu1)

    t3final = abs(b-mu2)+1

    n1 = numeric(t1final)

    n2 = numeric(t2final)

    n3 = numeric(t3final)

    for (i in 1:t1final) {n1[i] = (1+r1)^t1[i]}

    for (i in 1:t2final) {n2[i] = (n1[t1final])  * (1+r2)^t2[i]}

    for (i in 1:t3final) {n3[i] = (n2[t2final])  * (1+r3)^t3[i]}

    pop = c(n1,n2,n3)

    p = pop/sum(pop)

    res=a-rcat(n=1,prob=p)+1

    return(res)

  })

dQuadrupleExponentialGrowth=nimbleFunction(

  run = function(x = integer(0),a=double(0),b=double(0),r1=double(0),r2=double(0),r3=double(0),r4=double(0),mu1=double(0),mu2=double(0),mu3=double(0), log = integer(0)) {

    returnType(double(0))

    mu1 = round(mu1)

    mu2 = round(mu2)

    mu3 = round(mu3)

    t1 = 1:(abs(mu1-a))

    t2 = 1:(abs(mu2-mu1))

    t3 = 1:(abs(mu3-mu2))

    t4 = 1:(abs(b-mu3)+1)

    t1final = abs(mu1-a)

    t2final = abs(mu2-mu1)

    t3final = abs(mu3-mu2)

    t4final = abs(b-mu3)+1

    n1 = numeric(t1final)

    n2 = numeric(t2final)

    n3 = numeric(t3final)

    n4 = numeric(t4final)

    for (i in 1:t1final) {n1[i] = (1+r1)^t1[i]}

    for (i in 1:t2final) {n2[i] = (n1[t1final])  * (1+r2)^t2[i]}

    for (i in 1:t3final) {n3[i] = (n2[t2final])  * (1+r3)^t3[i]}

    for (i in 1:t4final) {n4[i] = (n3[t3final])  * (1+r4)^t4[i]}

    pop = c(n1,n2,n3,n4)

    p = pop/sum(pop)

    logProb = dcat(a-x+1,prob=p,log=TRUE)

    if(log) {

      return(logProb)

    } else {

      return(exp(logProb))

    }

  })

rQuadrupleExponentialGrowth = nimbleFunction(

  run = function(n=integer(0),a=double(0),b=double(0),r1=double(0),r2=double(0),r3=double(0),r4=double(0),mu1=double(0),mu2=double(0),mu3=double(0)) {

    returnType(double(0))

    mu1 = round(mu1)

    mu2 = round(mu2)

    mu3 = round(mu3)

    t1 = 1:(abs(mu1-a))

    t2 = 1:(abs(mu2-mu1))

    t3 = 1:(abs(mu3-mu2))

    t4 = 1:(abs(b-mu3)+1)

    t1final = abs(mu1-a)

    t2final = abs(mu2-mu1)

    t3final = abs(mu3-mu2)

    t4final = abs(b-mu3)+1

    n1 = numeric(t1final)

    n2 = numeric(t2final)

    n3 = numeric(t3final)

    n4 = numeric(t4final)

    for (i in 1:t1final) {n1[i] = (1+r1)^t1[i]}

    for (i in 1:t2final) {n2[i] = (n1[t1final])  * (1+r2)^t2[i]}

    for (i in 1:t3final) {n3[i] = (n2[t2final])  * (1+r3)^t3[i]}

    for (i in 1:t4final) {n4[i] = (n3[t3final])  * (1+r4)^t4[i]}

    pop = c(n1,n2,n3,n4)

    p = pop/sum(pop)

    res=a-rcat(n=1,prob=p)+1

    return(res)

  })

registerDistributions(list(

  dTripleExponentialGrowth = list(

    BUGSdist = "dTripleExponentialGrowth(a,b,r1,r2,r3,mu1,mu2)",

    Rdist = "dTripleExponentialGrowth(a,b,r1,r2,r3,mu1,mu2)",

    pqAvail = FALSE

  )))

registerDistributions(list(

  dQuadrupleExponentialGrowth = list(

    BUGSdist = "dQuadrupleExponentialGrowth(a,b,r1,r2,r3,r4,mu1,mu2,mu3)",

    Rdist = "dQuadrupleExponentialGrowth(a,b,r1,r2,r3,r4,mu1,mu2,mu3)",

    pqAvail = FALSE

  )))

## Generate Simulated Data ####

# Parameters:

a=7000

b=3000

mu1=6000

mu2=5000

mu3=4000

r1=0.002

r2=-0.001

r3=0.0005

r4=-0.0008

N=500

calendar.dates_c3=replicate(N,rTripleExponentialGrowth(1,a=a,b=b,r1=r1,r2=r2,r3=r3,mu1=mu1,mu2=mu2))

calendar.dates_c4=replicate(N,rQuadrupleExponentialGrowth(1,a=a,b=b,r1=r1,r2=r2,r3=r3,r4=r4,mu1=mu1,mu2=mu2,mu3=mu3))

## MCMC for dTripleExponentialGrowth (this works) ####

model3 <- nimbleCode({

  for (i in 1:N){

    X[i] ~ dTripleExponentialGrowth(a=a,b=b,r1=r1,r2=r2,r3=r3,mu1=chp1,mu2=chp2);

  }

  r1 ~ dnorm(0,0.004);

  r2 ~ dnorm(0,0.004);

  r3 ~ dnorm(0,0.004);

  alpha ~ dgamma(1, 1)

  for (j in 1:2) {v[j] ~ dbeta(1,alpha);}

  mu[1:3] <- stick_breaking(v[1:2]);

  for (k in 1:2)

  {

    chp[k] <- round(sum(mu[1:k]) * (b-a) + a);

  }

  chp1 <- chp[1];

  chp2 <- chp[2]

})

constants3 <- list(N=N,a=7000,b=3000)

data3 <- list(X=calendar.dates_c3)

init3 <- list(r1=0.002,r2=-0.001,r3=0.0005,v=c(0.2,0.2),alpha=0.6,chp1=5000,chp2=4000)

mcmc.samples3b<- nimbleMCMC(code = model3,constants = constants3,data = data3,niter = 5000, nchains = 1, thin=1, nburnin = 1000, progressBar = TRUE, monitors=c('r1','r2','r3','chp1','chp2'), inits=init3, samplesAsCodaMCMC=TRUE)

## MCMC for dQuadrupleExponentialGrowth (this fails) ####

model4 <- nimbleCode({

  for (i in 1:N){

    X[i] ~ dQuadrupleExponentialGrowth(a=7000,b=3000,r1=r1,r2=r2,r3=r3,r4=r4,mu1=chp1,mu2=chp2,mu3=chp3);

  }

  r1 ~ dnorm(0,0.004);

  r2 ~ dnorm(0,0.004);

  r3 ~ dnorm(0,0.004);

  r4 ~ dnorm(0,0.004);

  alpha ~ dgamma(1, 1)

  for (j in 1:3) {v[j] ~ dbeta(1,alpha);}

  mu[1:4] <- stick_breaking(v[1:3]);

  for (k in 1:3)

  {

    chp[k] <- round(sum(mu[1:k]) * (b-a) + a);

  }

  chp1 <- chp[1];

  chp2 <- chp[2];

  chp3 <- chp[3];

})

constants4 <- list(N=N,a=7000,b=3000)

data4 <- list(X=calendar.dates_c4)

init4 <- list(r1=0.002,r2=-0.001,r3=0.0005,r4=-0.0002,v=c(0.2,0.2,0.2),alpha=0.6,chp1=6000,chp2=5000,chp3=4000)

mcmc.samples4<- nimbleMCMC(code = model4,constants = constants4,data = data4,niter = 20000, nchains = 1, thin=1, nburnin = 5000, progressBar = TRUE, monitors=c('r1','r2','r3','r4','chp1','chp2','chp3'), inits=init4, samplesAsCodaMCMC=TRUE)

